import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/main.css";

export default function Home() {
  const [data, setData] = useState(null);
  const [currentSlide, setCurrentSlide] = useState(0);

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/home")
      .then((res) => setData(res.data))
      .catch((err) => console.error(err));
  }, []);

  if (!data) return <p>Loading...</p>;

  const nextSlide = () => {
    setCurrentSlide((prev) =>
      prev === data.activities.length - 1 ? 0 : prev + 1
    );
  };

  const prevSlide = () => {
    setCurrentSlide((prev) =>
      prev === 0 ? data.activities.length - 1 : prev - 1
    );
  };

  return (
    <main className="home-container">
      {/* Banner */}
      {data.bannerVideos?.length > 0 && (
        <section className="banner-section">
          <video
            className="banner-video"
            src={`http://localhost:5000${data.bannerVideos[0]}`}
            controls
            autoPlay
            loop
            muted
          />
        </section>
      )}

      {/* Welcome + Activities */}
      <section className="welcome-activities-container">
        {/* Left: Welcome text */}
        <div
          className="welcome-text"
          dangerouslySetInnerHTML={{ __html: data.welcomeText }}
        ></div>

        {/* Right: Activities slider */}
        <div className="activities-slider-wrapper">
          <h3>🏫 School Activities</h3>
          {data.activities.length > 0 && (
            <div className="activities-slider-single">
              <button className="slide-btn left" onClick={prevSlide}>
                &#10094;
              </button>
              <img
                src={`http://localhost:5000${data.activities[currentSlide]}`}
                alt={`activity-${currentSlide}`}
              />
              <button className="slide-btn right" onClick={nextSlide}>
                &#10095;
              </button>
            </div>
          )}
        </div>
      </section>

      {/* Testimonials */}
      {data.testimonialVideos?.length > 0 && (
        <section className="testimonials">
          <h2>🎬 Student Testimonials</h2>
          <div className="testimonial-grid">
            {data.testimonialVideos.map((vid, i) => (
              <video
                key={i}
                src={`http://localhost:5000${vid}`}
                controls
                className="testimonial-video"
              />
            ))}
          </div>
        </section>
      )}
    </main>
  );
}
